"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33741"],{68816(e){e.exports=JSON.parse('{"id":"V4-081","slug":"stakeholder-capitalism","term":"Stakeholder Capitalism","also_known_as":[],"difficulty":"Intermediate","definition":"Stakeholder capitalism is the idea that companies should aim to create long-term value for all their stakeholders, including employees, customers, suppliers, communities and the environment, not only for their shareholders.","explanation":["Stakeholder capitalism contrasts with shareholder primacy, the view, famously argued by economist Milton Friedman in 1970, that a company\u2019s main responsibility is to increase profits for its shareholders within the law.","Supporters argue that companies that treat employees fairly, serve customers well, support communities and protect the environment are more sustainable and successful in the long run, and that businesses have responsibilities beyond profit. In 2019, the Business Roundtable, a group of leading US chief executives, issued a statement redefining the purpose of a corporation to include all stakeholders, which drew wide attention.","For example, a company practising stakeholder capitalism might invest in training staff, pay suppliers promptly and reduce its emissions, even if these reduce short-term profits.","Critics argue that stakeholder capitalism blurs accountability, since managers serving many groups may effectively answer to none, and that it can be used to justify poor performance. Others argue that serving stakeholders and creating shareholder value are largely compatible over the long term. The debate is closely linked to ESG investing."],"note":"","total":1725,"prev":{"slug":"stakeholder","term":"Stakeholder"},"next":{"slug":"stamp-duty","term":"Stamp Duty"}}')}}]);